<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048 Dark Edition</title>
    <style>
        :root {
            --bg-color: #1a1a1b;
            --grid-bg: #3c3c3e;
            --tile-empty: #4d4d4f;
            --text-main: #ffffff;
            --accent: #edcf72;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-main);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
        }

        #score {
            font-size: 2rem;
            margin-bottom: 20px;
            font-weight: bold;
        }

        #board {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(4, 1fr);
            gap: 10px;
            background-color: var(--grid-bg);
            padding: 10px;
            border-radius: 8px;
            width: 320px;
            height: 320px;
        }

        .tile {
            width: 70px;
            height: 70px;
            background-color: var(--tile-empty);
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5rem;
            font-weight: bold;
            transition: transform 0.1s ease, background-color 0.2s;
        }

        #reset {
            margin-top: 30px;
            padding: 10px 25px;
            font-size: 1rem;
            cursor: pointer;
            background-color: var(--accent);
            border: none;
            border-radius: 4px;
            font-weight: bold;
            transition: opacity 0.2s;
        }

        #reset:hover {
            opacity: 0.8;
        }

        /* Tile Color Mapping */
        .tile-2 { background-color: #eee4da; color: #776e65; }
        .tile-4 { background-color: #ede0c8; color: #776e65; }
        .tile-8 { background-color: #f2b179; color: white; }
        .tile-16 { background-color: #f59563; color: white; }
        .tile-32 { background-color: #f67c5f; color: white; }
        .tile-64 { background-color: #f65e3b; color: white; }
        .tile-128 { background-color: #edcf72; color: white; font-size: 1.2rem; }
        .tile-256 { background-color: #edcf72; color: white; font-size: 1.2rem; }
        .tile-512 { background-color: #edcf72; color: white; font-size: 1.2rem; }
        .tile-1024 { background-color: #edcf72; color: white; font-size: 1rem; }
        .tile-2048 { background-color: #edcf72; color: white; font-size: 1rem; }
    </style>
</head>
<body>

    <div id="score">Score: 0</div>
    <div id="board"></div>
    <button id="reset">New Game</button>

    <script>
        const BOARD_SIZE = 4;
        let currentBoard = [];
        let currentScore = 0;

        const boardElement = document.getElementById('board');
        const scoreElement = document.getElementById('score');
        const resetBtn = document.getElementById('reset');

        // Initialize UI
        function initUI() {
            boardElement.innerHTML = '';
            for (let i = 0; i < BOARD_SIZE * BOARD_SIZE; i++) {
                const tile = document.createElement('div');
                tile.className = 'tile';
                tile.id = `tile-${i}`;
                boardElement.appendChild(tile);
            }
        }

        function render() {
            scoreElement.textContent = `Score: ${currentScore}`;
            for (let r = 0; r < BOARD_SIZE; r++) {
                for (let c = 0; c < BOARD_SIZE; c++) {
                    const val = currentBoard[r][c];
                    const tile = document.getElementById(`tile-${r * BOARD_SIZE + c}`);
                    tile.textContent = val === 0 ? '' : val;
                    tile.className = 'tile' + (val !== 0 ? ` tile-${val}` : '');
                }
            }
        }

        function spawnTile() {
            const emptyCells = [];
            for (let r = 0; r < BOARD_SIZE; r++) {
                for (let c = 0; c < BOARD_SIZE; c++) {
                    if (currentBoard[r][c] === 0) emptyCells.push({r, c});
                }
            }
            if (emptyCells.length > 0) {
                const cell = emptyCells[Math.floor(Math.random() * emptyCells.length)];
                currentBoard[cell.r][cell.c] = Math.random() < 0.9 ? 2 : 4;
            }
        }

        function slideRow(row) {
            // Filter out zeros
            let nonZeros = row.filter(v => v !== 0);
            let result = [];
            let i = 0;
            while (i < nonZeros.length) {
                if (i + 1 < nonZeros.length && nonZeros[i] === nonZeros[i+1]) {
                    result.push(nonZeros[i] * 2);
                    currentScore += nonZeros[i] * 2;
                    i += 2;
                } else {
                    result.push(nonZeros[i]);
                    i++;
                }
            }
            while (result.length < BOARD_SIZE) result.push(0);
            return result;
        }

        function move(direction) {
            let oldBoard = currentBoard.map(row => [...row]);

            if (direction === 'left' || direction === 'right') {
                for (let r = 0; r < BOARD_SIZE; r++) {
                    let row = currentBoard[r];
                    if (direction === 'right') row.reverse();
                    let newRow = slideRow(row);
                    if (direction === 'right') newRow.reverse();
                    currentBoard[r] = newRow;
                }
            } else {
                for (let c = 0; c < BOARD_SIZE; c++) {
                    let col = [];
                    for (let r = 0; r < BOARD_SIZE; r++) col.push(currentBoard[r][c]);
                    if (direction === 'down') col.reverse();
                    let newCol = slideRow(col);
                    if (direction === 'down') newCol.reverse();
                    for (let r = 0; r < BOARD_SIZE; r++) {
                        currentBoard[r][c] = newCol[r];
                    }
                }
            }

            const changed = JSON.stringify(oldBoard) !== JSON.stringify(currentBoard);
            if (changed) {
                spawnTile();
                render();
            }
            return changed;
        }

        // Programmatic API
        window.game = {
            size: BOARD_SIZE,
            reset() {
                currentBoard = Array(BOARD_SIZE).fill().map(() => Array(BOARD_SIZE).fill(0));
                currentScore = 0;
                // Start with 2 tiles
                let placed = 0;
                while (placed < 2) {
                    let r = Math.floor(Math.random() * BOARD_SIZE);
                    let c = Math.floor(Math.random() * BOARD_SIZE);
                    if (currentBoard[r][c] === 0) {
                        currentBoard[r][c] = 2;
                        placed++;
                    }
                }
                render();
            },
            move(dir) {
                const changed = move(dir);
                return changed;
            },
            board() {
                return currentBoard.map(row => [...row]);
            },
            setBoard(arr) {
                currentBoard = arr.map(row => [...row]);
                render();
            },
            score() {
                return currentScore;
            }
        };

        // Input Handlers
        window.addEventListener('keydown', (e) => {
            if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
                e.preventDefault();
                if (e.key === 'ArrowLeft') window.game.move('left');
                if (e.key === 'ArrowRight') window.game.move('right');
                if (e.key === 'ArrowUp') window.game.move('up');
                if (e.key === 'ArrowDown') window.game.move('down');
            }
        });

        resetBtn.addEventListener('click', () => {
            window.game.reset();
        });

        // Initialize Game
        initUI();
        window.game.reset();
    </script>
</body>
</html>
